const test = require('node:test');
const assert = require('node:assert/strict');
const {spawnSync} = require('node:child_process');
test('preservation comparison enforces exact pixels and repeatable failing command semantics', () => {
  const environment={...process.env}; delete environment.NODE_TEST_CONTEXT;
  const r=spawnSync(process.execPath,['--test','--test-reporter=tap','--test-name-pattern=preservation compare regression','scripts/ci/ui_preservation.test.cjs'],{
    cwd:'/Users/jon/projects/scrypath/.claude/worktrees/agent-p185-glue-u80ewc0s',env:environment,encoding:'utf8',timeout:30000,maxBuffer:4*1024*1024
  });
  assert.ifError(r.error); assert.match(r.stdout,/# tests 3\b/); assert.equal(r.status,0,r.stdout+r.stderr);
});
